"""Display the datasets generated by the experiment presets."""

from pathlib import Path

import matplotlib.pyplot as plt
from qiskit.quantum_info import Statevector

from qgan_v2.config.defaults import EXPERIMENT_PRESETS
from qgan_v2.datasets.images import create_images_dataset
from qgan_v2.datasets.quantum import create_quantum_dataset_circuits
from qgan_v2.visualization.utils import plot_basis_probabilities


def show_dataset_samples(preset, n_qubits, *, save_png=False, figure_dir=None):
    """Show every sample for each qubit count and optionally save each figure.

    Image sizes follow the angle or amplitude preset. The base preset's
    direct-quantum dataset uses the complete-basis probability plot shared
    with the results analysis output panels.
    """
    if preset not in EXPERIMENT_PRESETS:
        raise ValueError("preset must be 'base', 'ang', or 'amp'")

    qubit_counts = (n_qubits,) if isinstance(n_qubits, int) else tuple(n_qubits)
    if not qubit_counts or any(not isinstance(n, int) or n < 2 for n in qubit_counts):
        raise ValueError("n_qubits must contain integers of at least 2")

    output_dir = Path(figure_dir) if figure_dir is not None else Path("figures/datasets")
    if save_png:
        output_dir.mkdir(parents=True, exist_ok=True)

    figures = []
    for count in qubit_counts:
        if preset in {"ang", "amp"}:
            parameters = EXPERIMENT_PRESETS[preset]["dataset"]["parameters"](count)
            samples = create_images_dataset(
                EXPERIMENT_PRESETS[preset]["dataset"]["source"], parameters
            )
            columns = min(4, len(samples))
            rows = (len(samples) + columns - 1) // columns
            fig, axes = plt.subplots(rows, columns, figsize=(3 * columns, 3 * rows), squeeze=False)
            for index, (image, ax) in enumerate(zip(samples, axes.flat)):
                ax.imshow(image, cmap="gray", vmin=0, vmax=1, interpolation="nearest")
                ax.set_title(f"Sample {index + 1}")
                ax.axis("off")
            for ax in list(axes.flat)[len(samples):]:
                ax.axis("off")
            fig.suptitle(f"{preset} gradient images · {count} qubits · {samples.shape[1]} × {samples.shape[2]}")
        else:
            circuits = create_quantum_dataset_circuits({
                "dataset": {"source": EXPERIMENT_PRESETS[preset]["dataset"]["source"]},
                "experiment": {"n_qubits": count},
            })
            fig, axes = plt.subplots(len(circuits), 1, figsize=(9, max(3, 2 * len(circuits))), squeeze=False)
            for index, (circuit, ax) in enumerate(zip(circuits, axes.flat)):
                probabilities = Statevector(circuit).probabilities()
                plot_basis_probabilities(
                    ax, probabilities, count, title=f"Real data distribution {index}", color='C1'
                )
            fig.suptitle(f"base direct quantum distribution · {count} qubits")

        fig.tight_layout()
        if save_png:
            fig.savefig(output_dir / f"{preset}_q{count}.png", dpi=300, bbox_inches="tight")
        plt.show()
        figures.append(fig)
        if preset == "base":
            print(f"{count} qubits: {len(circuits)} sample(s)")
        else:
            print(f"{count} qubits: {len(samples)} sample(s), shape {samples.shape}")

    return figures
